import Link from 'next/link';
import { notFound } from 'next/navigation';
import { ArrowLeft, ArrowUpRight, ArrowRight } from 'lucide-react';
import { projects } from '@/content/projects';
import { ProjectVisual } from '@/components/project-visual';
export function generateStaticParams(){return projects.map(p=>({slug:p.slug}));}
export async function generateMetadata({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const p=projects.find(p=>p.slug===slug);return {title:p?`${p.name} — Gerald Donkor`:'Project not found',description:p?.description};}
export default async function ProjectPage({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const p=projects.find(p=>p.slug===slug);if(!p)notFound();const next=projects[(projects.indexOf(p)+1)%projects.length];return <><header className="header"><Link href="/" className="wordmark">gerald donkor<span>®</span></Link><Link href="/#work" className="header-contact"><ArrowLeft size={16}/> Back to work</Link></header><main className="case-study"><div className="case-intro"><Link href="/#work" className="back-link"><ArrowLeft size={15}/> All projects</Link><div className="section-top"><span className="eyebrow">PROJECT {p.number} / {p.category}</span><a className="inline-link" href={p.url} target="_blank" rel="noreferrer">Visit live site <ArrowUpRight size={20}/></a></div><h1>{p.name}<span className="accent">.</span></h1><p>{p.description}</p><div className="tag-list">{p.focus.map(t=><span key={t}>{t}</span>)}</div></div><ProjectVisual slug={p.slug}/><div className="case-body"><span className="eyebrow">THE EXPERIENCE</span><div><h2>{p.overview}</h2><ul>{p.highlights.map(h=><li key={h}>{h}</li>)}</ul><div className="case-links"><a href={p.url} target="_blank" rel="noreferrer">Explore the live project <ArrowUpRight size={18}/></a><a href={p.repo} target="_blank" rel="noreferrer">View the source <ArrowUpRight size={18}/></a></div></div></div><div className="case-next"><span className="eyebrow">UP NEXT / {next.number}</span><Link href={'/work/'+next.slug}>{next.name}<ArrowRight/></Link></div></main><footer><Link href="/" className="wordmark">gerald donkor<span>®</span></Link><a href="mailto:geralddonkor1@gmail.com">Let’s make something <ArrowUpRight size={15}/></a><span>© {new Date().getFullYear()}</span></footer></>}
